-- 0013_seed_80_day_plan_balanced.sql
--
-- The Strategic Study Calendar, full syllabus coverage, even daily load.
--
-- Supersedes 0011 and 0012. Run this one; skip both of those.
-- 80 days, 271 slots, all 243 microthemes, three or four topics every day.
--
-- How it differs from 0012
-- ------------------------
-- 0012 kept the calendar's day boundaries and appended the 70 missing
-- microthemes onto whichever day had room. Coverage was complete but the load
-- was lumpy: four days of two topics, five days of five to seven.
--
-- This version keeps the calendar's ORDER rather than its day boundaries. The
-- microthemes are taken in the sequence the calendar teaches them, each missing
-- one inserted directly after the last topic of its own subject, then the whole
-- 243 re-chunked into 71 learning days of three or four. Nothing is heavier
-- than four; nothing is lighter than three.
--
-- Eight revision days sit at the calendar's own block boundaries, each
-- repeating the three highest-tier microthemes of the block just finished --
-- looking back one block only, so the geography revision revises geography.
-- Day 80 is the OMR simulation, sampling one subject from each of four.
--
-- Two things carried over from the earlier migrations, still true here:
--
--   Mapping is by microtheme NAME, not the calendar's M-codes. The numberings
--   disagree in nineteen places -- M144 is labelled "Governor of Rajasthan"
--   while m144 here is the Central Vigilance Commission.
--
--   No day is ever empty. isDayClearedFor returns false for a day with no
--   topics, so an empty day can never be cleared and would stall the student.

update public.plan_templates set is_default = false where is_default and owner_id is null;

insert into public.plan_templates (id, name, blurb, scope, days, is_default, version, owner_id)
values (
