on conflict (id) do update
  set name = excluded.name, blurb = excluded.blurb, scope = excluded.scope,
      days = excluded.days, is_default = true,
      version = public.plan_templates.version + 1, updated_at = now();

-- Sanity: 80 days, 271 slots, 243 microthemes, no day outside 3-4 topics.
do $$
declare d int; s int; distinct_t int; bad int;
begin
  select jsonb_array_length(days) into d from public.plan_templates where id = 'ras-80-day-balanced';
  select count(*), count(distinct slot->>'topicId') into s, distinct_t
    from public.plan_templates t,
         lateral jsonb_array_elements(t.days) day,
         lateral jsonb_array_elements(day) slot
   where t.id = 'ras-80-day-balanced';
  select count(*) into bad
    from public.plan_templates t,
         lateral jsonb_array_elements(t.days) day
   where t.id = 'ras-80-day-balanced'
     and (jsonb_array_length(day) < 3 or jsonb_array_length(day) > 4);
  if d <> 80 or s <> 271 or distinct_t <> 243 or bad <> 0 then
    raise exception 'plan is % days / % slots / % microthemes / % days outside 3-4, expected 80 / 271 / 243 / 0',
      d, s, distinct_t, bad;
  end if;
end $$;
